  /* Two-line label shape used by esg-sections.js — array-of-arrays. */
  var FC_V3_ESG_LABELS_2LINE = [
    ['R1 Climate',         'Physical Risk'],
    ['R2 Grid Equity',     '& Social'],
    ['R3 Infrastructure',  'Resilience'],
    ['R4 Pollution',       '& Corrosion'],
    ['R5 Energy Trans.',   '& DER Stress'],
    ['R6 Cybersecurity',   'Exposure'],
    ['R7 SFDR PAI',        'Infrastructure']
  ];

  function computeR7SfdrPai(sub) {
    /* Per FC v3 §14 subsection 13.7 — R7 SFDR PAI is the W1-W10 governance gate reflected
       back into the ESG view. Authoritative formula is wired in
       apply-v4.2-modifiers.py Phase 4 (not yet shipped). Until then, the
       canonical proxy is Re_norm — the resilience composite IS the structural
       driver of PAI Infrastructure exposure. This is a Convention #7 (Data-Layer Anchoring)
       documented proxy, NOT a fabricated value (Re_norm is fully canonical). */
    if (sub == null) return null;
    if (typeof sub.R7_sfdr_pai === 'number') return sub.R7_sfdr_pai;  // forward-compat
    if (typeof sub.Re_norm === 'number') return sub.Re_norm;          // documented proxy
    return null;
  }

  function patchEsgRadarChart(sub) {
    if (!sub || typeof window.Chart === 'undefined') {
      console.warn('[canada-v4.2-override] ESG radar patch skipped — Chart.js not loaded or no sub');
      return;
    }
    var canvas = document.getElementById('esgRadar');
    if (!canvas) { console.warn('[canada-v4.2-override] ESG radar patch skipped — #esgRadar canvas not found'); return; }
    var chart = window.Chart.getChart ? window.Chart.getChart(canvas) : null;
    if (!chart) { console.warn('[canada-v4.2-override] ESG radar patch skipped — no Chart.js instance attached to #esgRadar'); return; }

    var d = chart.data;
    if (!d || !Array.isArray(d.labels) || !Array.isArray(d.datasets) || d.datasets.length === 0) {
      console.warn('[canada-v4.2-override] ESG radar patch skipped — chart.data shape unexpected');
      return;
    }
    var ds0 = d.datasets[0];
    if (!Array.isArray(ds0.data)) {
      console.warn('[canada-v4.2-override] ESG radar patch skipped — dataset.data not an array');
      return;
    }

    if (chart.__canadaV42Patched === true) {
      // Already patched — quiet no-op.
      return;
    }

    /* Detect label shape: array-of-arrays (two-line) or array-of-strings. */
    var L = d.labels;
    var twoLineShape = Array.isArray(L[0]);

    /* Pre-FC-v3 ordering detection — coerce L[3] / L[4] to string and regex.
       Works for both shapes (arrays toString() → comma-joined). */
    var s3 = Array.isArray(L[3]) ? L[3].join(' ') : String(L[3] || '');
    var s4 = Array.isArray(L[4]) ? L[4].join(' ') : String(L[4] || '');
    var isPreV3Order = (L.length === 6 && /energy/i.test(s3) && /pollut/i.test(s4));

    if (isPreV3Order) {
      // Swap labels[3] ↔ labels[4] and the matching dataset entries.
      var tmpL = L[3]; L[3] = L[4]; L[4] = tmpL;
      var tmpV = ds0.data[3]; ds0.data[3] = ds0.data[4]; ds0.data[4] = tmpV;
      if (Array.isArray(ds0.pointBackgroundColor)) {
        var tmpC = ds0.pointBackgroundColor[3];
        ds0.pointBackgroundColor[3] = ds0.pointBackgroundColor[4];
        ds0.pointBackgroundColor[4] = tmpC;
      }
    }

    /* Rewrite to canonical FC v3 §14 labels — PRESERVING the original shape. */
    var canonical = twoLineShape ? FC_V3_ESG_LABELS_2LINE : FC_V3_ESG_LABELS_FLAT;
    for (var i = 0; i < 6; i++) {
      L[i] = canonical[i];
    }

    /* Append R7 SFDR PAI as 7th axis, value derived from canonical Re_norm. */
    var r7 = computeR7SfdrPai(sub);
    if (r7 != null) {
      L.push(canonical[6]);
      ds0.data.push(r7);
      // Match pointBackgroundColor ordering — append a bronze token color.
      if (Array.isArray(ds0.pointBackgroundColor)) {
        ds0.pointBackgroundColor.push(TOKENS.bronze);
      }
    }

    chart.__canadaV42Patched = true;
    /* Chart.js v4 — explicit 'none' mode skips animation but forces axis
       refresh (the scales auto-recompute from labels.length). Without an
       update mode the radar may keep the old 6-axis grid until the next
       resize event. */
    try {
      chart.update('none');
    } catch (e) {
      chart.update();
    }
    console.log('[canada-v4.2-override] ESG Radar patched to FC v3 §14 — '
      + L.length + ' axes (R4/R5 swapped, R7 SFDR PAI added, label shape: '
      + (twoLineShape ? 'two-line preserved' : 'flat strings') + ')');
  }

