  /* ═══════════════════════════════════════════════════════════════════════
     Component Fingerprint — left text legend + right Chart.js bar patch
     ═══════════════════════════════════════════════════════════════════════
     The shared esg-sections.js uses v4.0.2 ESG-flavoured component labels
     (C=Condition, I=Insulation, E=Environment, S=Seismic) that do NOT match
     the SSI v4.2 canonical labels used on every other page (Continuity,
     Infrastructure, Economic, Saturation). This patch:
       (i)  Relabels the 6 left-legend rows + chart bars to v4.2 canonical
       (ii) Appends a 7th Re composite row to the left text legend so it
            aligns row-for-row with the 7-bar right chart (Convention #11)
       (iii) Appends Re composite as 7th horizontal bar on the chart
     v4.2 canonical map (CVIEST per CONVENTIONS.md Convention #31).
     ═══════════════════════════════════════════════════════════════════════ */
  var V42_COMPONENT_LABELS = {
    C: 'Continuity',
    V: 'Voltage',
    I: 'Infrastructure',
    E: 'Economic',
    S: 'Saturation',
    T: 'Transition'
  };

  function patchComponentLegendV42Labels(sub) {
    var legend = document.getElementById('componentLegend');
    if (!legend) return;
    if (legend.__canadaV42LabelsPatched) return;
    var items = legend.querySelectorAll('.component-legend-item');
    if (items.length < 6) return;  // shared JS not done yet — retry
    var keys = ['C', 'V', 'I', 'E', 'S', 'T'];
    items.forEach(function (item, i) {
      if (i >= 6) return;
      // The label span sits between the dot and the score span — overwrite text.
      var spans = item.getElementsByTagName('span');
      if (spans.length >= 1) spans[0].textContent = V42_COMPONENT_LABELS[keys[i]] || spans[0].textContent;
    });
    legend.__canadaV42LabelsPatched = true;
    console.log('[canada-v4.2-override] esg-report — componentLegend labels patched to v4.2 canonical (Continuity/Voltage/Infrastructure/Economic/Saturation/Transition)');
  }

  function computeRbase(sub) {
    if (!sub || !sub.components) return null;
    var weights = { C: 0.30, V: 0.10, I: 0.25, E: 0.10, S: 0.20, T: 0.05 };
    var total = 0;
    Object.keys(weights).forEach(function (k) {
      var v = sub.components[k];
      if (typeof v === 'number') total += v * weights[k];
    });
    return total;
  }

  function appendRbaseTotalRow(sub) {
    var legend = document.getElementById('componentLegend');
    if (!legend) return;
    if (legend.querySelector('[data-v42-rbase-total-row]')) return;  // idempotent
    var rbase = computeRbase(sub);
    if (rbase == null) return;
    var html =
      '<div class="component-legend-item" data-v42-rbase-total-row="1" style="border-top:1px solid rgba(44,36,32,0.18);margin-top:8px;padding-top:8px;background:rgba(44,36,32,0.03)">' +
        '<div class="component-legend-dot" style="background:var(--ink);opacity:0.85;"></div>' +
        '<span style="font-weight:700;color:var(--ink)">R<sub>base</sub> total <span style="font-size:10px;font-weight:500;color:var(--warm-grey)">(weighted sum)</span></span>' +
        '<span class="component-legend-score" style="font-weight:700;color:var(--ink)">' + rbase.toFixed(3) + '</span>' +
        '<span class="component-legend-weight" style="color:var(--warm-grey)" title="R_base = 0.30·C + 0.10·V + 0.25·I + 0.10·E + 0.20·S + 0.05·T &mdash; the base resilience score before modifiers + Re composite are applied.">&Sigma; = 1.00</span>' +
      '</div>';
    legend.insertAdjacentHTML('beforeend', html);
    console.log('[canada-v4.2-override] esg-report — R_base total row appended (R_base=' + rbase.toFixed(3) + ')');
  }

  function appendReToComponentBar(sub) {
    // The main stacked #componentBar shows 6 R_base segments (C/V/I/E/S/T). Methodologically
    // Re composite is NOT in R_base, so it can't be a 7th segment of the stacked bar — but
    // leaving it out of the bar surface entirely while the legend has 7 rows creates a visual
    // misalignment (legend row points at nothing). We append a small SECOND row of bar surface
    // immediately below #componentBar so the legend's 7th row (Re composite) has a visible bar
    // counterpart, kept methodologically separated by a thin separator + a "(not in R_base)" caveat.
    if (!sub || typeof sub.Re_norm !== 'number') return;
    var bar = document.getElementById('componentBar');
    if (!bar) return;
    if (bar.parentNode && bar.parentNode.querySelector('[data-v42-re-bar]')) return;  // idempotent
    var reNorm = Math.max(0, Math.min(sub.Re_norm, 1));
    var reBand = reNorm >= 0.50 ? 'elevated' : reNorm >= 0.25 ? 'moderate' : 'low';
    var reColor = reNorm >= 0.50 ? TOKENS.terracotta : reNorm >= 0.25 ? TOKENS.bronze : TOKENS.sage;
    // Mirror the structural shape of #componentBar so the visual weight matches.
    var barClass = bar.className || '';   // typically "component-bar"
    var wrap = document.createElement('div');
    wrap.setAttribute('data-v42-re-bar', '1');
    wrap.style.cssText = 'margin-top:6px;padding-top:6px;border-top:1px dashed rgba(170,66,52,0.22);position:relative';
    // Caveat label (extra-small, terracotta).
    var caveat = document.createElement('div');
    caveat.style.cssText = 'font-size:9px;color:' + TOKENS.terracotta + ';text-transform:uppercase;letter-spacing:0.06em;font-weight:600;margin-bottom:4px;display:flex;justify-content:space-between;align-items:center';
    caveat.innerHTML = '<span>v4.2 Re composite (aggregate, NOT in R<sub>base</sub>)</span><span style="font-weight:500;color:' + reColor + ';text-transform:none;letter-spacing:0">' + reBand + ' exposure</span>';
    wrap.appendChild(caveat);
    // The Re bar itself — same class as the parent so it inherits height + radius + spacing.
    var reBar = document.createElement('div');
    reBar.className = barClass;
    reBar.style.cssText = 'position:relative';
    var reSegment = document.createElement('div');
    reSegment.style.cssText = 'width:' + (reNorm * 100).toFixed(1) + '%;background:' + reColor + ';color:#fff;text-shadow:0 1px 1px rgba(0,0,0,0.25);display:flex;align-items:center;justify-content:center;font-weight:600;font-size:11px';
    reSegment.title = 'Re_norm = ' + reNorm.toFixed(3) + ' on [0, 1] scale. Bounded aggregate of R6c flood + R6d wildfire + R6e winter + R8 adapt + R9 compound + R10 just modifiers. Shown alongside the R_base stack for visual coherence with the right-hand chart and the 7-row legend; NOT summed into R_base.';
    reSegment.textContent = 'Re';
    reBar.appendChild(reSegment);
    wrap.appendChild(reBar);
    // Insert after the main bar but before the legend.
    bar.parentNode.insertBefore(wrap, bar.nextSibling);
    console.log('[canada-v4.2-override] esg-report — Re composite bar appended below #componentBar (Re_norm=' + reNorm.toFixed(3) + ')');
  }

  function appendReToComponentLegend(sub) {
    if (!sub || typeof sub.Re_norm !== 'number') return;
    var legend = document.getElementById('componentLegend');
    if (!legend) return;
    if (legend.querySelector('[data-v42-re-legend-row]')) return;  // idempotent
    var reNorm = sub.Re_norm;
    var reBand = reNorm >= 0.50 ? 'elevated' : reNorm >= 0.25 ? 'moderate' : 'low';
    var reColor = reNorm >= 0.50 ? TOKENS.terracotta : reNorm >= 0.25 ? TOKENS.bronze : TOKENS.sage;
    // Mirror the shared component-legend-item DOM shape (dot + label + score + weight).
    // For Re: weight slot becomes "agg" since Re is the modifier-family aggregate (not in R_base).
    var html =
      '<div class="component-legend-item" data-v42-re-legend-row="1" style="border-top:1px dashed rgba(170,66,52,0.22);margin-top:6px;padding-top:6px">' +
        '<div class="component-legend-dot" style="background:' + TOKENS.terracotta + ';"></div>' +
        '<span style="color:' + TOKENS.terracotta + ';font-weight:600">Re composite <span style="font-size:9px;font-weight:500">v4.2 aggregate</span></span>' +
        '<span class="component-legend-score" style="color:' + reColor + ';font-weight:600">' + reNorm.toFixed(3) + '</span>' +
        '<span class="component-legend-weight" style="color:var(--warm-grey)" title="Re composite is the v4.2 modifier-family aggregate (R6c+R6d+R6e+R8+R9+R10); shown for comparison alongside R_base components but NOT summed into R_base (R_base = 0.30C + 0.10V + 0.25I + 0.10E + 0.20S + 0.05T uses only the 6 components above).">agg</span>' +
      '</div>';
    legend.insertAdjacentHTML('beforeend', html);
    console.log('[canada-v4.2-override] esg-report — componentLegend extended with 7th Re composite row (Re_norm=' + reNorm.toFixed(3) + ')');
  }

  function patchComponentChart(sub) {
    if (!sub || typeof window.Chart === 'undefined') return;
    if (typeof sub.Re_norm !== 'number') return;   // v4.0.2 cohort fall-through (Convention #3)
    var canvas = document.getElementById('componentChart');
    if (!canvas) return;
    var chart = window.Chart.getChart ? window.Chart.getChart(canvas) : null;
    if (!chart || chart.__canadaV42ComponentChartPatched) return;
    var d = chart.data;
    if (!d || !Array.isArray(d.labels) || !Array.isArray(d.datasets) || d.datasets.length === 0) return;
    var ds = d.datasets[0];
    if (!Array.isArray(ds.data)) return;
    // (i) Relabel the 6 existing bars to v4.2 canonical so they match the left legend.
    //     Shared JS emits labels in COMP_CONFIG iteration order: C, V, I, E, S, T
    var v42Labels = ['Continuity', 'Voltage', 'Infrastructure', 'Economic', 'Saturation', 'Transition'];
    for (var i = 0; i < Math.min(d.labels.length, v42Labels.length); i++) {
      d.labels[i] = v42Labels[i];
    }
    // (ii) Append Re composite as the 7th bar — terracotta-tinted.
    d.labels.push('Re composite (v4.2 aggregate)');
    ds.data.push(Math.max(0, Math.min(sub.Re_norm, 1)));
    if (Array.isArray(ds.backgroundColor)) ds.backgroundColor.push(TOKENS.terracotta + 'cc');
    if (Array.isArray(ds.borderColor))     ds.borderColor.push(TOKENS.terracotta);
    chart.__canadaV42ComponentChartPatched = true;
    try { chart.update('none'); } catch (e) { chart.update(); }
    console.log('[canada-v4.2-override] esg-report — componentChart patched: 6 bars relabelled to v4.2 canonical + 7th Re composite bar appended (Re_norm=' + sub.Re_norm.toFixed(3) + ')');
  }

