    var reBand = (reNorm >= 0.50) ? 'elevated' : (reNorm >= 0.25) ? 'moderate' : 'low';
    var reColor = (reNorm >= 0.50) ? TOKENS.terracotta : (reNorm >= 0.25) ? TOKENS.bronze : TOKENS.sage;
    var readiness = (reNorm != null) ? 'ready' : 'gap';
